#!/usr/bin/env node
/**
 * Verifies that a production Android build does not request INTERNET.
 *
 * Usage:
 *   node scripts/verify-offline-manifest.js [path/to/AndroidManifest.xml]
 *
 * With no argument it checks the merged release manifest produced by Gradle
 * (android/app/build/intermediates/merged_manifests/release/...) and falls back
 * to the source manifest generated by `expo prebuild`.
 * For an APK you can also run: aapt dump permissions app-release.apk
 */
const fs = require('fs');
const path = require('path');

const candidates = process.argv[2]
  ? [process.argv[2]]
  : [
      'android/app/build/intermediates/merged_manifests/release/processReleaseManifest/AndroidManifest.xml',
      'android/app/build/intermediates/merged_manifests/release/AndroidManifest.xml',
      'android/app/src/main/AndroidManifest.xml',
    ];

const file = candidates.map((c) => path.resolve(c)).find((c) => fs.existsSync(c));
if (!file) {
  console.error('No AndroidManifest.xml found. Run `APP_VARIANT=production npx expo prebuild -p android` first.');
  process.exit(2);
}

const xml = fs.readFileSync(file, 'utf8');
const requests = [...xml.matchAll(/<uses-permission[^>]*android\.permission\.INTERNET[^>]*>/g)].filter(
  (m) => !/tools:node="remove"/.test(m[0]),
);

if (requests.length > 0) {
  console.error(`FAIL: ${file} requests android.permission.INTERNET`);
  process.exit(1);
}
console.log(`OK: ${file} does not request android.permission.INTERNET`);
